"""Detect and preserve mandatory notes generated by the knowledge-graph agent."""

import json
import re
from collections.abc import Iterable

CODE_FENCE_PATTERN = re.compile(r"```.*?```", re.DOTALL)
SENTENCE_BOUNDARY_PATTERN = re.compile(r"(?<=[.!?])\s+")
PROVENANCE_PATTERN = re.compile(
    r"(?:^|\s)(?:provenance|fuente|source|origen|informe)\s*:",
    re.IGNORECASE,
)
ROOT_CARD_PATTERN = re.compile(r"\broot\s*=\s*Card\s*\(")
DISCLAIMER_TRIGGERS = (
    "interpretación generada por un modelo de lenguaje",
    "interpretation generated by a language model",
    "no es un dato de la fecha",
    "hecho verificado",
    "not a verified fact",
)
IN_SAMPLE_TRIGGERS = (
    "in-sample",
    "in sample",
    "en muestra",
    "dentro de muestra",
)


def _normalize_note(note: str) -> str:
    return " ".join(note.split())


def merge_notes(notes: Iterable[str]) -> tuple[str, ...]:
    """Deduplicate notes while preserving their first-seen order."""
    merged: list[str] = []
    seen: set[str] = set()
    for note in notes:
        normalized = _normalize_note(note)
        if normalized and normalized not in seen:
            seen.add(normalized)
            merged.append(normalized)
    return tuple(merged)


def _contains_any(text: str, triggers: tuple[str, ...]) -> bool:
    folded = text.casefold()
    return any(trigger in folded for trigger in triggers)


def extract_mandatory_notes(text: str) -> tuple[str, ...]:
    """Extract verbatim generated-text, in-sample and provenance notes."""
    cleaned = CODE_FENCE_PATTERN.sub("\n", text)
    notes: list[str] = []

    for block in re.split(r"\n\s*\n", cleaned):
        block = block.strip()
        if not block:
            continue
        lines = block.splitlines()
        provenance_lines = [line.strip() for line in lines if PROVENANCE_PATTERN.search(line)]
        notes.extend(provenance_lines)
        body = "\n".join(line for line in lines if not PROVENANCE_PATTERN.search(line)).strip()
        if not body:
            continue
        sentences = [part.strip() for part in SENTENCE_BOUNDARY_PATTERN.split(body) if part.strip()]
        for index, sentence in enumerate(sentences):
            if _contains_any(sentence, DISCLAIMER_TRIGGERS):
                notes.append(" ".join(sentences[index:]))
                break
            if _contains_any(sentence, IN_SAMPLE_TRIGGERS):
                notes.append(sentence)

    return merge_notes(notes)


def _note_present(openui_lang: str, note: str) -> bool:
    if note in openui_lang:
        return True
    escaped = json.dumps(note, ensure_ascii=False)[1:-1]
    return escaped in openui_lang


def _matching_bracket(text: str, start: int) -> int:
    depth = 0
    quote: str | None = None
    escaped = False
    for index in range(start, len(text)):
        character = text[index]
        if quote is not None:
            if escaped:
                escaped = False
            elif character == "\\":
                escaped = True
            elif character == quote:
                quote = None
            continue
        if character in {'"', "'"}:
            quote = character
        elif character == "[":
            depth += 1
        elif character == "]":
            depth -= 1
            if depth == 0:
                return index
    return -1


def _root_card_bounds(text: str) -> tuple[int, int] | None:
    match = ROOT_CARD_PATTERN.search(text)
    if match is None:
        return None
    opening = text.find("[", match.end())
    if opening == -1:
        return None
    closing = _matching_bracket(text, opening)
    if closing == -1:
        return None
    return opening, closing


def append_missing_notes(openui_lang: str, notes: Iterable[str]) -> str:
    """Append any missing note as a small TextContent and reference it from root."""
    mandatory = merge_notes(notes)
    missing = [note for note in mandatory if not _note_present(openui_lang, note)]
    if not missing:
        return openui_lang
    bounds = _root_card_bounds(openui_lang)
    if bounds is None:
        return openui_lang

    opening, closing = bounds
    existing_names = set(re.findall(r"\bmandatoryNote\d+\b", openui_lang))
    statements: list[str] = []
    references: list[str] = []
    next_index = 1
    for note in missing:
        while f"mandatoryNote{next_index}" in existing_names:
            next_index += 1
        name = f"mandatoryNote{next_index}"
        existing_names.add(name)
        references.append(name)
        statements.append(f'{name} = TextContent({json.dumps(note, ensure_ascii=False)}, "small")')
        next_index += 1

    inner = openui_lang[opening + 1 : closing]
    if inner.strip():
        separator = "" if inner.rstrip().endswith(",") else ","
        addition = f"{separator} {', '.join(references)}"
    else:
        addition = ", ".join(references)
    updated = f"{openui_lang[:closing]}{addition}{openui_lang[closing:]}"
    return f"{updated.rstrip()}\n" + "\n".join(statements)


def preserve_mandatory_notes(openui_lang: str, source_text: str) -> str:
    """Extract mandatory notes from source text and append missing ones."""
    return append_missing_notes(openui_lang, extract_mandatory_notes(source_text))
